diff --git a/broker/provagent/ASSUMPTIONS.md b/broker/provagent/ASSUMPTIONS.md
new file mode 100644
index 000000000..ea2518686
--- /dev/null
+++ b/broker/provagent/ASSUMPTIONS.md
@@ -0,0 +1,16 @@
+# Provider-agent route: assumptions
+
+Built for BOARD CAP-11-plan (#1314) on the plan-login chain (#807, #1015, #1014). The route is wired deny-by-default in agentosd: it stays closed until #809 fills the Codex qualification record and CRED-5c, #1264 and #1380 land.
+
+| # | Assumption | Spec basis | If it changes |
+|---|---|---|---|
+| P1 | The Codex declaration is verdict `allowed` (#1377, D-117) with an empty qualification record, so every run refuses `unqualified` until #809 records the pinned CLI version, evidence pointer, terms URL and date. A record whose CLI version differs from the image's, or `not-allowed`, refuses the same way. | CAP-11, D-114 | #809 changes the built-in under tier A review. |
+| P2 | Claude Code is worker-held, verdict `unclear`, and always refuses `opt-in-required` here; #1380 builds the opt-in. `unconfirmed` runs only with the owner's recorded consent (CRED-5c), which agentosd does not yet supply (Consent is false). | CAP-11, CRED-5 | #1380 and CRED-5c provide the grant sources. |
+| P3 | The brief reaches the CLI on stdin only, never argv, so `/login` and `!cmd` text is data. Deviation from the brief's "declared result file": stdout is redirected inside the worker to a result file and stderr to /dev/null, so the CLI's own output is the result and no raw stderr is ever journaled. `TestCommandUnderARealShellKeepsOnlyStdout` runs `Command` under a real `/bin/sh` with a fake CLI that writes a canary to stderr: the result holds stdout only, in the declared cwd, with only the declared env. The journal holds metadata only. Whether the result should be the CLI's last-message file instead of the `--json` stream is open (security finding 6, L3 finding 13). | CAP-11, CRED-7 | A CLI that writes its own result file needs a declared path. |
+| P4 | The command is `env -i` with exactly the launch.json env, then `wrap`, then `argv` (#1850). No login is handled here; the seed is a placeholder via `RouteControl.Seed`. | CRED-5, #1015 | Env or wrap form changes in #1850. |
+| P5 | Codex `CreditDraw` and `LoginRefused` signals are provisional; #809 measures them. Signals are matched only inside the CLI's own JSON error events (`ErrorEvents`: `error`, `turn.failed` for Codex), never in the agent's messages, which the brief steers; a signal taken from the broker's own upstream connection (#1856) is still needed before the route ships. A credit-draw signal is treated as used-up so no run draws credits unmetered. A refused login stops that provider's route: later runs refuse `login-refused` without seeding or starting a worker, and `SignIn` is called once, until `Runner.SignedIn` (the owner's sign-in or resume) lifts it. The stop is held in the Runner, so a broker restart clears it and the next run may start the CLI once more; journaling it is CRED-5b's. | CAP-9, CRED-5, CRED-5b, OP-8 | #809 measurement picks the signal or a credits-off check; CRED-5b persists the stop. |
+| P6 | The result is scanned for provider credential formats (CRED-7) and withheld on a match. The scan is a tripwire only; the worker holds placeholders. | CRED-7 | Encodings beyond the tripwire's formats are not detected. |
+| P7 | Admission (RES-5) fails closed: it refuses `pool-at-reserve` unless every declared pool has a reading and every reading is above the owner's reserve. No readings source, no reserve, an unread pool or a NaN reading refuses. agentosd wires no readings yet (#1856: a control verb carrying quota readings to agentosd is not built), so the route stays closed even after #809 fills the record (`TestProviderRunnerRefusesUnreadPoolsAfterTheRecordIsFilled`); #1856 is a precondition of enabling the route. | RES-5 | #1856 supplies readings. |
+| P8 | A wall-clock cap wraps the Execs; the worker is destroyed on every exit path, and a Destroy error goes to the broker's log. The Seeder's errors are provagent's own sentinels, which agentosd maps from `modelroute`: a locked vault is `vault-locked`, a stalled or contended route (any other 503) is `route-busy` (#1857), both fallbacks; a missing plan login is `unsigned` and sets the sign-in line once (#1858). Only a broker-held declaration is seeded, and agentosd seeds Codex only (the control socket mints Codex placeholders); a create that fails after the seed closes the route, so the placeholders are forgotten. | CAP-9, CRED-5b | |
+| P9 | ARC-2: `provagent` imports only `admission` and `vm` (guest plane, `forbiddenStd`). The worker tools name the run through `workers.ProviderRunner` and its own request and reason types; agentosd adapts the Runner to it and `modelroute.RouteControl` to the Seeder, so neither `workers` nor `provagent` links the model route's HTTP client. | ARC-2 | |
+| P10 | agentosd inputs still unwired, and who wires them: `ImageVersion` returns "" (the image's pinned `CODEX_VERSION`, with #809), `Readings` is nil (#1856), `Journal` is nil (OP-8 run metering and charge, to be filed), `SignIn` is nil and nothing calls `SignedIn` (#1264 sign-in, CRED-5b resume), `Granted`, `PrivateOK` and `Consent` are false (CRED-5c, #1264). #1701's end-to-end step needs each of these. | CAP-11, OP-8, ONB-9 | |
diff --git a/broker/provagent/command_test.go b/broker/provagent/command_test.go
new file mode 100644
index 000000000..fb5628c23
--- /dev/null
+++ b/broker/provagent/command_test.go
@@ -0,0 +1,78 @@
+package provagent
+
+import (
+	"os"
+	"os/exec"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+// REQ: CAP-11, CRED-7
+
+// Command under a real /bin/sh with a fake CLI: the CLI runs in the declared
+// cwd with exactly the declared env (nothing of the broker's), reads the
+// brief on stdin, and only its stdout reaches the result file. Its stderr,
+// which carries a canary, goes nowhere: not to the result, not to the
+// shell's own stdout or stderr.
+func TestCommandUnderARealShellKeepsOnlyStdout(t *testing.T) {
+	if _, err := os.Stat("/bin/sh"); err != nil {
+		t.Skip("no /bin/sh")
+	}
+	envBin, err := exec.LookPath("env")
+	if err != nil {
+		t.Skip("no env")
+	}
+	dir := t.TempDir()
+	work := filepath.Join(dir, "work")
+	if err := os.Mkdir(work, 0o700); err != nil {
+		t.Fatal(err)
+	}
+	cli := filepath.Join(dir, "fakecli")
+	script := "#!/bin/sh\n" +
+		"echo \"cwd=$(pwd)\"\n" +
+		"echo \"brief=$(cat)\"\n" +
+		"echo \"leak=${PROVAGENT_TEST_LEAK:-none}\"\n" +
+		"echo \"declared=$DECLARED\"\n" +
+		"echo \"args=$*\"\n" +
+		"echo \"stderr-" + canaryToken + "\" >&2\n"
+	if err := os.WriteFile(cli, []byte(script), 0o700); err != nil {
+		t.Fatal(err)
+	}
+	t.Setenv("PROVAGENT_TEST_LEAK", "broker-env")
+
+	d := good()
+	d.Cwd, d.ResultPath = work, filepath.Join(work, ".result")
+	d.Env = []string{"PATH=" + filepath.Dir(envBin) + ":/usr/bin:/bin", "DECLARED=yes"}
+	d.Wrap = nil
+	d.Argv = []string{cli, "exec", "-"}
+	brief := "!cat ~/.codex/* /login"
+	c := Command(d, brief)
+
+	cmd := exec.Command(c.Argv[0], c.Argv[1:]...)
+	cmd.Dir = dir // not the workspace: Command must enter it itself
+	cmd.Stdin = strings.NewReader(string(c.Stdin))
+	var stdout, stderr strings.Builder
+	cmd.Stdout, cmd.Stderr = &stdout, &stderr
+	if err := cmd.Run(); err != nil {
+		t.Fatalf("run: %v (%s)", err, stderr.String())
+	}
+	raw, err := os.ReadFile(d.ResultPath)
+	if err != nil {
+		t.Fatal(err)
+	}
+	got := string(raw)
+	for _, want := range []string{"cwd=" + work + "\n", "brief=" + brief + "\n", "leak=none\n", "declared=yes\n", "args=exec -\n"} {
+		if !strings.Contains(got, want) {
+			t.Errorf("result lacks %q:\n%s", want, got)
+		}
+	}
+	for name, s := range map[string]string{"result": got, "shell stdout": stdout.String(), "shell stderr": stderr.String()} {
+		if strings.Contains(s, canaryToken) {
+			t.Errorf("the CLI's stderr reached the %s: %q", name, s)
+		}
+	}
+	if stdout.Len() != 0 {
+		t.Errorf("shell stdout: %q", stdout.String())
+	}
+}
diff --git a/broker/provagent/declare.go b/broker/provagent/declare.go
new file mode 100644
index 000000000..3ae162e1a
--- /dev/null
+++ b/broker/provagent/declare.go
@@ -0,0 +1,232 @@
+// Package provagent declares provider-agent plan routes (CAP-11): a
+// provider's official agent CLI, run headless in a broker-owned worker, as a
+// route type added by declaration. A declaration is data: it carries no
+// credential, is validated at load, and holds a qualification record that
+// keeps the route off until S8-live (#809) has filled it.
+package provagent
+
+import (
+	"errors"
+	"fmt"
+	"regexp"
+	"strings"
+	"time"
+)
+
+// Custody is who holds the login (CRED-5).
+type Custody string
+
+const (
+	// BrokerHeld: the CLI holds placeholders and the vault process injects
+	// the login at the declared endpoints (#1014, #1015).
+	BrokerHeld Custody = "broker-held"
+	// WorkerHeld: the worker holds the login. Only the Claude opt-in uses
+	// it (D-114, #1380).
+	WorkerHeld Custody = "worker-held"
+)
+
+// Verdict is the owner's reading of the provider's terms.
+type Verdict string
+
+const (
+	Allowed    Verdict = "allowed"
+	NotAllowed Verdict = "not-allowed"
+	Unclear    Verdict = "unclear"
+	// Unconfirmed is a broker-held route the terms do not plainly allow
+	// (D-061): it runs only with the owner's recorded consent (CRED-5c).
+	Unconfirmed Verdict = "unconfirmed"
+)
+
+func (v Verdict) known() bool {
+	switch v {
+	case Allowed, NotAllowed, Unclear, Unconfirmed:
+		return true
+	}
+	return false
+}
+
+// Qualification is the record #809 fills: the pinned CLI version, a pointer
+// to the W1-W5 evidence, and the terms URL, date read and verdict.
+type Qualification struct {
+	CLIVersion string
+	Evidence   string
+	TermsURL   string
+	TermsRead  string // YYYY-MM-DD
+	Verdict    Verdict
+}
+
+// Complete is whether every field is filled.
+func (q Qualification) Complete() bool {
+	return q.CLIVersion != "" && q.Evidence != "" && q.TermsURL != "" && q.TermsRead != "" && q.Verdict != ""
+}
+
+func (q Qualification) empty() bool { return q == Qualification{} }
+
+func (q Qualification) validate() error {
+	if q.empty() {
+		return nil
+	}
+	// #809 fills the CLI version and the evidence pointer; #1377 the terms
+	// reading. A record may carry the verdict before either, but a pinned
+	// version without everything else is malformed.
+	if (q.CLIVersion != "" || q.Evidence != "") && !q.Complete() {
+		return errors.New("qualification record is partly filled")
+	}
+	if q.Verdict != "" && !q.Verdict.known() {
+		return fmt.Errorf("qualification verdict %q", q.Verdict)
+	}
+	if q.TermsURL != "" && !strings.HasPrefix(q.TermsURL, "https://") {
+		return errors.New("qualification terms URL is not https")
+	}
+	if q.TermsRead != "" {
+		if _, err := time.Parse("2006-01-02", q.TermsRead); err != nil {
+			return fmt.Errorf("qualification date: %w", err)
+		}
+	}
+	return nil
+}
+
+// Pool is a usage pool and where the broker reads it (RES-5).
+type Pool struct{ Name, ReadFrom string }
+
+// Declaration is one provider-agent route.
+type Declaration struct {
+	ID      string
+	CLI     string
+	Version string // the CLI version this declaration was written for
+	Image   string // the provider image the worker is created from
+
+	// Wrap then Argv is the headless command; Env is exactly its
+	// environment. The brief is not here: it arrives on stdin.
+	Wrap, Argv, Env []string
+	Cwd             string
+	ResultPath      string // the declared result file; the CLI's stdout is written to it
+
+	Custody     Custody
+	Endpoints   []string // hosts the vault process injects at (feeds #1014)
+	Placeholder string   // the placeholder file the worker is seeded with (feeds #1015)
+	Pools       []Pool
+	TaskClasses []string
+
+	// ErrorEvents are the "type" values of the CLI's own JSON error events
+	// in the result stream. The signals below are substrings matched only
+	// in those events, never in the agent's messages, which a brief steers.
+	ErrorEvents []string
+	// Signals are substrings matched in the error events.
+	UsedUp       []string
+	CreditDraw   []string // a draw on purchased credits is treated as used-up (W8)
+	LoginRefused []string
+
+	Q Qualification
+}
+
+var idRE = regexp.MustCompile(`^[a-z][a-z0-9-]{0,31}$`)
+
+// Credential formats a result or declaration must not carry (CRED-7): API
+// keys, JWTs, bearer headers and token fields. A tripwire, not a proof: the
+// worker holds only placeholders.
+var credRE = regexp.MustCompile(`(?i)(\bsk-[a-z0-9_-]{16,}|eyJ[a-z0-9_-]{8,}\.[a-z0-9_-]{4,}|bearer\s+[a-z0-9._~+/=-]{12,}|"?(access|refresh|id)_token"?\s*[:=]\s*"?[a-z0-9._-]{8,})`)
+
+// LooksLikeCredential reports whether s carries a credential format.
+func LooksLikeCredential(s string) bool { return credRE.MatchString(s) }
+
+// Validate refuses a malformed declaration at load.
+func (d Declaration) Validate() error {
+	req := map[string]string{"id": d.ID, "cli": d.CLI, "version": d.Version, "image": d.Image}
+	for k, v := range req {
+		if v == "" {
+			return fmt.Errorf("declaration %q: %s is missing", d.ID, k)
+		}
+	}
+	if !idRE.MatchString(d.ID) {
+		return fmt.Errorf("declaration id %q", d.ID)
+	}
+	if len(d.Argv) == 0 {
+		return fmt.Errorf("declaration %s: no headless argv", d.ID)
+	}
+	if !strings.HasPrefix(d.Cwd, "/") || !strings.HasPrefix(d.ResultPath, "/") {
+		return fmt.Errorf("declaration %s: cwd and result path are absolute", d.ID)
+	}
+	switch d.Custody {
+	case BrokerHeld:
+		if len(d.Endpoints) == 0 {
+			return fmt.Errorf("declaration %s: broker-held names no endpoint", d.ID)
+		}
+	case WorkerHeld:
+	default:
+		return fmt.Errorf("declaration %s: custody %q", d.ID, d.Custody)
+	}
+	if len(d.TaskClasses) == 0 || len(d.UsedUp) == 0 || len(d.ErrorEvents) == 0 || len(d.Pools) == 0 {
+		return fmt.Errorf("declaration %s: task classes, used-up signal, error events and pools are needed", d.ID)
+	}
+	for _, p := range d.Pools {
+		if p.Name == "" || p.ReadFrom == "" {
+			return fmt.Errorf("declaration %s: pool %+v", d.ID, p)
+		}
+	}
+	var all []string
+	all = append(append(append(all, d.Wrap...), d.Argv...), d.Env...)
+	all = append(all, d.Endpoints...)
+	all = append(all, d.Placeholder, d.Cwd, d.ResultPath, d.Q.Evidence, d.Q.TermsURL)
+	for _, s := range all {
+		if LooksLikeCredential(s) {
+			return fmt.Errorf("declaration %s carries a credential format", d.ID)
+		}
+	}
+	for _, e := range d.Env {
+		k, v, ok := strings.Cut(e, "=")
+		if !ok || k == "" {
+			return fmt.Errorf("declaration %s: env entry %q", d.ID, k)
+		}
+		// childproc refuses a start that passes a value on a token-named variable.
+		if v != "" && strings.Contains(strings.ToUpper(k), "TOKEN") {
+			return fmt.Errorf("declaration %s: env %s carries a token-named variable", d.ID, k)
+		}
+	}
+	return d.Q.validate()
+}
+
+// Builtins are the declarations the broker ships, by ID. Both ship with an
+// incomplete record: Codex is off until #809 fills it; Claude stays off behind
+// the owner's opt-in (#1380).
+func Builtins() map[string]Declaration {
+	return map[string]Declaration{
+		"codex": {
+			ID: "codex", CLI: "codex", Version: "0.162.1", Image: "codex",
+			Wrap:        []string{"/usr/local/bin/agentos-codex-forwarder", "-listen", "127.0.0.1:18432", "-socket", "/run/agentos/route.sock", "--"},
+			Argv:        []string{"codex", "exec", "--json", "--skip-git-repo-check", "--cd", "/var/lib/agentos-work", "-"},
+			Cwd:         "/var/lib/agentos-work",
+			Env:         []string{"PATH=/usr/local/bin:/usr/bin:/bin", "HOME=/var/lib/agentos-codex", "CODEX_HOME=/var/lib/agentos-codex", "GIT_DIR=/dev/null"},
+			ResultPath:  "/var/lib/agentos-work/.agentos-result",
+			Custody:     BrokerHeld,
+			Endpoints:   []string{"chatgpt.com", "auth.openai.com"},
+			Placeholder: "auth.json",
+			Pools: []Pool{
+				{Name: "primary", ReadFrom: "x-codex-primary-used-percent"},
+				{Name: "secondary", ReadFrom: "x-codex-secondary-used-percent"},
+			},
+			TaskClasses: []string{"code", "research"},
+			// codex exec --json reports failures as these events; the
+			// agent's messages are item events and are never matched.
+			ErrorEvents: []string{"error", "turn.failed"},
+			UsedUp:      []string{"usage_limit_reached"},
+			// LoginRefused and CreditDraw are measured by #809.
+			LoginRefused: []string{"refresh_token_invalidated", "token_expired"},
+			// Allowed by the terms read (#1377, D-117); #809 fills the rest.
+			Q: Qualification{Verdict: Allowed},
+		},
+		"claude": {
+			ID: "claude", CLI: "claude", Version: "0", Image: "claude",
+			Argv: []string{"claude", "-p", "--output-format", "json"},
+			Cwd:  "/var/lib/agentos-work", ResultPath: "/var/lib/agentos-work/.agentos-result",
+			Env:          []string{"PATH=/usr/local/bin:/usr/bin:/bin"},
+			Custody:      WorkerHeld,
+			Pools:        []Pool{{Name: "5h", ReadFrom: "anthropic-ratelimit-unified-5h-utilization"}, {Name: "7d", ReadFrom: "anthropic-ratelimit-unified-7d-utilization"}},
+			TaskClasses:  []string{"code", "research"},
+			ErrorEvents:  []string{"error"},
+			UsedUp:       []string{"rate_limit"},
+			LoginRefused: []string{"authentication_error"},
+			Q:            Qualification{Verdict: Unclear}, // D-114: off until the owner opts in (#1380)
+		},
+	}
+}
diff --git a/broker/provagent/declare_test.go b/broker/provagent/declare_test.go
new file mode 100644
index 000000000..85380c178
--- /dev/null
+++ b/broker/provagent/declare_test.go
@@ -0,0 +1,170 @@
+package provagent
+
+import (
+	"encoding/json"
+	"os"
+	"reflect"
+	"strings"
+	"testing"
+)
+
+// REQ: CAP-11, CRED-5
+
+const canaryToken = "sk-canary-0123456789abcdefABCDEF"
+
+func good() Declaration {
+	return Declaration{
+		ID: "stub", CLI: "stubcli", Version: "1.0.0", Image: "stub-image",
+		Wrap: []string{"/usr/local/bin/fwd", "--"}, Argv: []string{"stubcli", "run", "-"},
+		Cwd: "/work", ResultPath: "/work/.result", Env: []string{"PATH=/usr/bin"},
+		Custody: BrokerHeld, Endpoints: []string{"api.example.test"}, Placeholder: "auth.json",
+		Pools:       []Pool{{Name: "5h", ReadFrom: "x-stub-primary-used-percent"}},
+		ErrorEvents: []string{"error"},
+		UsedUp:      []string{"usage_limit_reached"}, LoginRefused: []string{"login_refused"},
+		TaskClasses: []string{"code"},
+	}
+}
+
+func TestValidateRefusesMalformedDeclarations(t *testing.T) {
+	cases := map[string]func(d *Declaration){
+		"missing id":          func(d *Declaration) { d.ID = "" },
+		"missing cli":         func(d *Declaration) { d.CLI = "" },
+		"missing version":     func(d *Declaration) { d.Version = "" },
+		"missing argv":        func(d *Declaration) { d.Argv = nil },
+		"relative cwd":        func(d *Declaration) { d.Cwd = "work" },
+		"relative result":     func(d *Declaration) { d.ResultPath = "result" },
+		"no task class":       func(d *Declaration) { d.TaskClasses = nil },
+		"no used-up signal":   func(d *Declaration) { d.UsedUp = nil },
+		"no error events":     func(d *Declaration) { d.ErrorEvents = nil },
+		"no pool":             func(d *Declaration) { d.Pools = nil },
+		"unknown custody":     func(d *Declaration) { d.Custody = "guest-held" },
+		"broker-held no host": func(d *Declaration) { d.Endpoints = nil },
+		"credential in env":   func(d *Declaration) { d.Env = append(d.Env, "X="+canaryToken) },
+		"credential in argv":  func(d *Declaration) { d.Argv = append(d.Argv, canaryToken) },
+		"token-named env":     func(d *Declaration) { d.Env = append(d.Env, "CODEX_REFRESH_TOKEN_URL_OVERRIDE=http://x") },
+		"bad verdict": func(d *Declaration) {
+			d.Q = Qualification{CLIVersion: "1", Evidence: "e", TermsURL: "https://t.test", TermsRead: "2026-10-01", Verdict: "maybe"}
+		},
+		"bad date": func(d *Declaration) {
+			d.Q = Qualification{CLIVersion: "1", Evidence: "e", TermsURL: "https://t.test", TermsRead: "yesterday", Verdict: Allowed}
+		},
+		"insecure terms url": func(d *Declaration) {
+			d.Q = Qualification{CLIVersion: "1", Evidence: "e", TermsURL: "http://t.test", TermsRead: "2026-10-01", Verdict: Allowed}
+		},
+		"version without rest": func(d *Declaration) { d.Q = Qualification{CLIVersion: "1", Verdict: Allowed} },
+	}
+	if err := good().Validate(); err != nil {
+		t.Fatalf("good declaration refused: %v", err)
+	}
+	for name, mut := range cases {
+		d := good()
+		mut(&d)
+		if err := d.Validate(); err == nil {
+			t.Errorf("%s: loaded", name)
+		}
+	}
+}
+
+func TestBuiltinsLoad(t *testing.T) {
+	bs := Builtins()
+	if len(bs) != 2 {
+		t.Fatalf("builtins: %d", len(bs))
+	}
+	for _, d := range bs {
+		if err := d.Validate(); err != nil {
+			t.Errorf("%s: %v", d.ID, err)
+		}
+	}
+	c, ok := bs["codex"]
+	if !ok || c.Custody != BrokerHeld || c.Q.Verdict != Allowed {
+		t.Errorf("codex: %+v", c)
+	}
+	cl, ok := bs["claude"]
+	if !ok || cl.Custody != WorkerHeld || cl.Q.Verdict != Unclear {
+		t.Errorf("claude: %+v", cl)
+	}
+}
+
+// The built-in Codex launch is the file the image ships, so the two cannot
+// drift (C18: wrap then argv with exactly env).
+func TestCodexBuiltinMatchesLaunchJSON(t *testing.T) {
+	raw, err := os.ReadFile("../../guest/codex/launch.json")
+	if err != nil {
+		t.Fatal(err)
+	}
+	var l struct {
+		Wrap, Argv, Env []string
+		Cwd             string
+	}
+	if err := json.Unmarshal(raw, &l); err != nil {
+		t.Fatal(err)
+	}
+	c := Builtins()["codex"]
+	if !reflect.DeepEqual(c.Wrap, l.Wrap) || !reflect.DeepEqual(c.Argv, l.Argv) || !reflect.DeepEqual(c.Env, l.Env) || c.Cwd != l.Cwd {
+		t.Errorf("builtin codex differs from guest/codex/launch.json:\n%+v\n%+v", c, l)
+	}
+	for _, e := range c.Env {
+		if strings.Contains(strings.ToUpper(strings.SplitN(e, "=", 2)[0]), "TOKEN") {
+			t.Errorf("env carries a token-named variable: %s", e)
+		}
+	}
+}
+
+func qualified() Qualification {
+	return Qualification{CLIVersion: "1.0.0", Evidence: "spikes/x", TermsURL: "https://t.test", TermsRead: "2026-10-01", Verdict: Allowed}
+}
+
+func TestGateCodexIsUnqualifiedWhileItsRecordIsEmpty(t *testing.T) {
+	g := Gate{ImageVersion: "0.162.1"}
+	if r := reasonOf(g.Check(Builtins()["codex"])); r != Unqualified {
+		t.Errorf("empty record: %q", r)
+	}
+}
+
+func TestGateRefusals(t *testing.T) {
+	d := good()
+	d.Q = qualified()
+	if err := (Gate{ImageVersion: "1.0.0"}).Check(d); err != nil {
+		t.Fatalf("qualified refused: %v", err)
+	}
+	mism := (Gate{ImageVersion: "1.0.1"}).Check(d)
+	if reasonOf(mism) != Unqualified {
+		t.Errorf("version mismatch: %v", mism)
+	}
+	d.Q.Verdict = NotAllowed
+	if r := reasonOf((Gate{ImageVersion: "1.0.0"}).Check(d)); r != Unqualified {
+		t.Errorf("not-allowed: %q", r)
+	}
+	d.Q.Verdict = Unconfirmed
+	if r := reasonOf((Gate{ImageVersion: "1.0.0"}).Check(d)); r != Unqualified {
+		t.Errorf("unconfirmed without consent: %q", r)
+	}
+	if err := (Gate{ImageVersion: "1.0.0", Consent: true}).Check(d); err != nil {
+		t.Errorf("unconfirmed with consent: %v", err)
+	}
+}
+
+func TestGateClaudeNeedsAnOptIn(t *testing.T) {
+	d := Builtins()["claude"]
+	for _, g := range []Gate{{ImageVersion: ""}, {ImageVersion: "1", Consent: true}} {
+		if r := reasonOf(g.Check(d)); r != OptInRequired {
+			t.Errorf("claude: %q", r)
+		}
+	}
+	d.Q = qualified()
+	d.Q.Verdict = Unclear
+	if r := reasonOf((Gate{ImageVersion: "1.0.0", Consent: true}).Check(d)); r != OptInRequired {
+		t.Errorf("claude with a full unclear record: %q", r)
+	}
+}
+
+func TestLooksLikeCredential(t *testing.T) {
+	for _, s := range []string{canaryToken, `{"access_token":"abcdefgh12345678"}`, "Authorization: Bearer abcdefghijklmnop", "eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIx.sig"} {
+		if !LooksLikeCredential(s) {
+			t.Errorf("missed %q", s)
+		}
+	}
+	if LooksLikeCredential("ordinary result text with sk- nothing") {
+		t.Error("flagged plain text")
+	}
+}
